// Advanced-mode Pages worker: serves the site images (the deploy tooling can only commit text),
// and hands every other request to the static assets (so _redirects and clean URLs still apply).
const IMAGES = {
  "/logo-arena-publica.webp": "",
  "/logo-uai.webp": "",
  "/logo-hbs.webp": "",
  "/logo-tec.webp": "",
  "/logo-edinburgh.webp": "",
  "/logo-scrum.webp": "",
  "/logo-bdo.webp": "",
  "/logo-clara.webp": "",
  "/logo-dpl-news.webp": "",
  "/logo-el-economista.webp": "",
  "/logo-el-tiempo.webp": "",
  "/logo-endeavor.webp": "",
  "/logo-expansion.webp": "",
  "/logo-falabella.webp": "",
  "/logo-grin.webp": "",
  "/logo-iep.webp": "",
  "/logo-la-republica.webp": "",
  "/logo-linio.webp": "",
  "/logo-mastercard.webp": "",
  "/logo-reuters.webp": "",
  "/logo-semana.webp": "",
  "/logo-universidad-santo-tomas.webp": "",
  "/logo-valora-analitik.webp": "",
  "/stage-talk.webp": "",
  "/stage-recap.webp": "",
  "/stage-amazon.webp": "",
  "/stage-mbta.webp": "",
  "/portrait-stage.webp": "",
  "/og-image.jpg": "",
  "/portrait.jpg": "",
  "/portrait-hero.webp": "",
  "/favicon.ico": "",
  "/favicon-32.png": "",
  "/apple-touch-icon.png": "",
  "/icon-192.png": "",
  "/icon-512.png": "",
};
const TYPES = { ".jpg": "image/jpeg", ".webp": "image/webp", ".png": "image/png", ".ico": "image/x-icon" };
const cache = {};
const SEC = {
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "strict-origin-when-cross-origin",
  "X-Frame-Options": "SAMEORIGIN",
  "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
  "Strict-Transport-Security": "max-age=31536000",
};
// Belt and braces: also apply the security headers to anything served from static assets.
async function withSec(res) {
  const r = new Response(res.body, res);
  for (const [k, v] of Object.entries(SEC)) if (!r.headers.has(k)) r.headers.set(k, v);
  return r;
}
function bytes(path) {
  if (!cache[path]) {
    const bin = atob(IMAGES[path]);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    cache[path] = out;
  }
  return cache[path];
}
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (Object.prototype.hasOwnProperty.call(IMAGES, url.pathname)) {
      const body = request.method === "HEAD" ? null : bytes(url.pathname);
      return new Response(body, {
        headers: { ...SEC, "content-type": TYPES[url.pathname.slice(url.pathname.lastIndexOf("."))], "cache-control": "public, max-age=86400" },
      });
    }
    const HIDDEN = { "/familia": "/", "/familia.html": "/", "/familia/": "/", "/family": "/en/", "/en/family": "/en/", "/en/family.html": "/en/", "/en/family/": "/en/" };
    if (Object.prototype.hasOwnProperty.call(HIDDEN, url.pathname)) {
      return Response.redirect(new URL(HIDDEN[url.pathname], url.origin).toString(), 302);
    }
    if (url.pathname.startsWith("/functions/") || url.pathname === "/_worker.js" || url.pathname === "/_headers") {
      return new Response("Not found", { status: 404 });
    }
    return withSec(await env.ASSETS.fetch(request));
  },
};
